using Spine.Unity;
using UnityEngine;
using Object = UnityEngine.Object;

namespace MyClone.SpineSystem.Tests
{
	/// <summary>
	/// Builds a tiny synthetic Spine 3.8 skeleton + atlas + texture at runtime.
	/// No game assets are used: every byte below is generated by this test project.
	/// </summary>
	public sealed class TestSpineAssets
	{
		public const string SkeletonJson = @"{
""skeleton"": { ""hash"": ""myclone-test"", ""spine"": ""3.8.99"", ""x"": -32, ""y"": -32, ""width"": 64, ""height"": 64 },
""bones"": [
	{ ""name"": ""root"" },
	{ ""name"": ""bone1"", ""parent"": ""root"", ""x"": 8, ""y"": 8 }
],
""slots"": [
	{ ""name"": ""slot1"", ""bone"": ""bone1"", ""attachment"": ""img1"" },
	{ ""name"": ""slot2"", ""bone"": ""root"", ""attachment"": ""img2"" }
],
""skins"": [
	{ ""name"": ""default"", ""attachments"": {
		""slot1"": { ""img1"": { ""width"": 16, ""height"": 16 } },
		""slot2"": { ""img2"": { ""width"": 16, ""height"": 16 } }
	} },
	{ ""name"": ""alt"", ""attachments"": {
		""slot1"": { ""alt1"": { ""width"": 16, ""height"": 16 } }
	} }
],
""animations"": {
	""idle"": { ""bones"": { ""bone1"": { ""rotate"": [ { ""time"": 0, ""angle"": 0 }, { ""time"": 0.5, ""angle"": 90 } ] } } },
	""once"": { ""bones"": { ""bone1"": { ""rotate"": [ { ""time"": 0, ""angle"": 0 }, { ""time"": 0.2, ""angle"": 45 } ] } } }
}
}";

		public const string AtlasText = @"
testpage.png
size: 64, 64
format: RGBA8888
filter: Linear, Linear
repeat: none
img1
  rotate: false
  xy: 0, 0
  size: 16, 16
  orig: 16, 16
  offset: 0, 0
  index: -1
img2
  rotate: false
  xy: 16, 0
  size: 16, 16
  orig: 16, 16
  offset: 0, 0
  index: -1
alt1
  rotate: false
  xy: 32, 0
  size: 16, 16
  orig: 16, 16
  offset: 0, 0
  index: -1
";

		public SkeletonDataAsset Data { get; private set; }
		public SpineAtlasAsset Atlas { get; private set; }
		public TextAsset SkeletonText { get; private set; }
		public TextAsset AtlasTextAsset { get; private set; }
		public Texture2D Texture { get; private set; }

		public static TestSpineAssets Create (string uiShaderName = "Spine/SkeletonGraphic")
		{
			var result = new TestSpineAssets ();

			result.Texture = new Texture2D (64, 64, TextureFormat.RGBA32, false);
			result.Texture.name = "testpage";
			var pixels = new Color32[64 * 64];
			for (int i = 0; i < pixels.Length; i++)
				pixels[i] = new Color32 (255, 255, 255, 255);
			result.Texture.SetPixels32 (pixels);
			result.Texture.Apply ();

			result.AtlasTextAsset = new TextAsset (AtlasText);
			result.Atlas = SpineAtlasAsset.CreateRuntimeInstance (
				result.AtlasTextAsset,
				new[] { result.Texture },
				Shader.Find (uiShaderName),
				true);

			result.SkeletonText = new TextAsset (SkeletonJson);
			result.Data = SkeletonDataAsset.CreateRuntimeInstance (
				result.SkeletonText,
				result.Atlas,
				true,
				0.01f);

			return result;
		}

		public void Destroy ()
		{
			if (Data != null)
				Object.DestroyImmediate (Data);
			if (Atlas != null)
				Object.DestroyImmediate (Atlas);
			if (SkeletonText != null)
				Object.DestroyImmediate (SkeletonText);
			if (AtlasTextAsset != null)
				Object.DestroyImmediate (AtlasTextAsset);
			if (Texture != null)
				Object.DestroyImmediate (Texture);

			Data = null;
			Atlas = null;
			SkeletonText = null;
			AtlasTextAsset = null;
			Texture = null;
		}
	}
}
